<?php
require_once __DIR__ . '/../../includes/admin_auth.php'; require_admin();
$search = trim((string) ($_GET['q'] ?? ''));
$statement = $pdo->prepare('SELECT id, title, image, category, status, created_at FROM gallery WHERE CONCAT_WS(" ", title, category, description) LIKE :search ORDER BY id DESC');
$statement->execute(['search' => '%' . $search . '%']); $items = $statement->fetchAll(); admin_header('Gallery', 'gallery/index.php');
?><div class="d-flex flex-wrap gap-2 justify-content-between mb-3"><form class="d-flex gap-2" method="get"><input class="form-control" name="q" value="<?= e($search) ?>" placeholder="Search gallery..."><button class="btn btn-outline-secondary" type="submit"><i class="bi bi-search"></i></button></form><a href="create.php" class="btn btn-primary"><i class="bi bi-plus-lg me-1"></i>Add Image</a></div><div class="card table-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Image</th><th>Title</th><th>Category</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><img src="../../<?= e(image_url($item['image'], 'gallery')) ?>" alt="<?= e($item['title']) ?>" style="width:64px;height:48px;object-fit:cover;border-radius:8px"></td><td><strong><?= e($item['title']) ?></strong></td><td><?= e($item['category']) ?></td><td><span class="badge text-bg-<?= $item['status'] ? 'success' : 'secondary' ?>"><?= $item['status'] ? 'Active' : 'Inactive' ?></span></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="edit.php?id=<?= e($item['id']) ?>">Edit</a> <a class="btn btn-sm btn-outline-danger" href="delete.php?id=<?= e($item['id']) ?>">Delete</a></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="5" class="text-center text-secondary py-5">No gallery images found.</td></tr><?php endif; ?></tbody></table></div></div><?php admin_footer(); ?>